    CHECK(vc == 3 && vlong == 1 && vstop == SALCFGIMP_VSTOP_NONE); // "*.jpg;*.png" (11 bytes) is left out
    CHECK(vc == 3 && strcmp(vs[2].Masks, "*.after") == 0);
